<script setup lang="ts">
import {formatBytes} from './format-bytes';
import {historyStatuses,historyPhases,historyTimeText,reasonLabels,type HistoryRun} from './cloud-history-types';
defineProps<{record:HistoryRun;observedAt:string}>();
const missing='历史未记录';
const comparisonLabels:Record<string,string>={no_previous_run:'没有可用的前次记录',current_snapshot_unrecorded:'本轮覆盖快照未记录',previous_snapshot_unrecorded:'前轮覆盖快照未记录',comparable:'可比较'};
</script>
<template><section class="history-summary"><h3>固定运行摘要</h3><p>{{historyStatuses[record.status]||record.status}} · {{historyPhases[record.phase]||record.phase}}。这是持久记录，不代表当前执行器状态。</p><dl class="path-settings-overview"><div><dt>开始 UTC</dt><dd>{{historyTimeText(record.started_at_utc)}}</dd><dt>更新 UTC</dt><dd>{{historyTimeText(record.updated_at_utc)}}</dd></div><div><dt>摘要本机读取 UTC</dt><dd>{{observedAt}}</dd><dt>历史错误</dt><dd>{{record.last_error||'未记录错误'}}</dd></div></dl><p v-if="record.source==='hash'">已校验 {{record.processed_files}} / {{record.total_files}} 文件 · {{formatBytes(record.processed_bytes)}} / {{formatBytes(record.total_bytes)}} · 后续文件游标 {{record.next_fs_id}}</p><template v-else><p>范围 / 目录：{{record.source==='refresh'?record.root_path:record.current_directory}}</p><p>{{record.items_processed}} 项 / {{record.pages_processed}} 页 · 待处理 {{record.pending_count}} 目录 · 工具请求 {{record.requests_used}} / {{record.request_budget==='0'?'不限':record.request_budget}}</p></template><template v-if="record.source==='scan'"><h3>本轮历史覆盖快照</h3><p class="muted">这是当时记录的快照，不能作为当前缓存完整性的证明。缺失字段不补成零。</p><div class="event-table-scroll"><table><thead><tr><th>覆盖状态</th><th>未完整目录</th><th>代次</th><th>快照 UTC</th></tr></thead><tbody><tr><td>{{record.coverage_status??missing}}</td><td data-testid="history-coverage-incomplete">{{record.coverage_incomplete_directories??missing}}</td><td>{{record.coverage_generation??missing}}</td><td>{{historyTimeText(record.coverage_observed_at_utc)}}</td></tr></tbody></table></div><details><summary>原因与前轮比较</summary><div class="event-table-scroll"><table><thead><tr><th>原因</th><th>当时数量</th><th>前轮数量</th><th>差值</th></tr></thead><tbody><tr v-for="(name,key) in reasonLabels" :key="key"><td>{{name}}</td><td>{{record.coverage_reasons?.[key]??missing}}</td><td>{{record.coverage_comparison?.previous_reasons?.[key]??missing}}</td><td>{{record.coverage_comparison?.reason_deltas?.[key]??missing}}</td></tr></tbody></table></div><template v-if="record.coverage_comparison"><p>比较状态：{{comparisonLabels[record.coverage_comparison.status]||record.coverage_comparison.status}} · {{record.coverage_comparison.reason_status||'原因比较未记录'}}</p><p>前轮 ID：{{record.coverage_comparison.previous_run_id||'未记录'}}<br>前轮快照 UTC：{{historyTimeText(record.coverage_comparison.previous_observed_at_utc)}}<br>未完整目录差值：{{record.coverage_comparison.incomplete_directories_delta??missing}}</p></template><p v-else>{{missing}}比较信息。</p></details></template></section></template>
